# Independent literal port of 08_archive/code/5_WGBS_Functional-enrichement-analysis-BOTH.R
# (lines 72-85, 186-206, 210-303, 321-938), written with the same dplyr/tidyr calls as the
# legacy script, run on the ORIGINAL legacy input files downloaded from gannet
# (not on the files regenerated by pipeline step 08, and not using any pipeline helper).
# Output: an RDS with every intermediate table, and a csv of the counts.

.libPaths(c("/home/user/gannet_cache/legacy_r_lib", .libPaths()))   # GO.db 3.13.0
suppressPackageStartupMessages({
  library(GO.db); library(topGO); library(dplyr); library(tidyr)
})
stopifnot(as.character(packageVersion("GO.db")) == "3.13.0")
scratch <- "/tmp/claude-0/-home-user-WGBS-gigas-ploidy-desiccation/ed665b6a-3457-5aca-a521-7838dbc31cfa/scratchpad/wf/C7-legacy-go-semantics"
src <- "/home/user/gannet_cache/legacy_goannot"
cols <- c("transcript", "geneID", "chr", "start", "end", "meth.diff", "GOID", "GOterm", "GOSlim", "GOcat")
files <- c(PLOIDY = "DML-Cov10-20-BOTH-PLOIDY.GOAnnot", HEAT = "DML-Cov10-20-BOTH-HEAT.GOAnnot",
           COMBO = "DML-Cov10-20-BOTH-COMBO.GOAnnot")

# legacy lines 72-85: read.table with defaults (quote = "\"'", comment.char = "#")
DMLGOterms <- lapply(files, function(f) suppressWarnings(
  read.table(file.path(src, f), header = FALSE, sep = "\t", col.names = cols)))
# exact reader, every line a row (for comparison only)
DMLGOterms_exact <- lapply(files, function(f)
  read.table(file.path(src, f), header = FALSE, sep = "\t", col.names = cols, quote = "", comment.char = "",
             stringsAsFactors = FALSE))

# legacy lines 186-189
geneID2GO <- topGO::readMappings(file = file.path(src, "geneid2go-union1x-BOTH.tab"))
geneNames <- names(geneID2GO)

onts <- c(BP = "P", CC = "C", MF = "F")
test.stat <- new("classicCount", testStatistic = GOFisherTest, name = "Fisher test")
out <- list(); counts <- list()
for (s in names(files)) {
  Genes <- DMLGOterms[[s]]$transcript                       # legacy 193
  GeneList <- factor(as.integer(geneNames %in% Genes))      # legacy 194
  names(GeneList) <- geneNames                              # legacy 195
  for (o in names(onts)) {
    # legacy 210-246: a NEW topGOdata object per set and ontology
    GOdata <- suppressMessages(new("topGOdata", ontology = o, allGenes = GeneList,
                                   annot = annFUN.gene2GO, gene2GO = geneID2GO))
    # legacy 255-303
    resultFisher <- suppressMessages(getSigGroups(GOdata, test.stat))
    pvalFis <- score(resultFisher)
    allRes <- GenTable(GOdata, classic = resultFisher, ranksOf = "classic", orderBy = "classic",
                       topNodes = length(pvalFis))
    # legacy 345-351 (BP), 544-550 (CC), 743-749 (MF)
    allDMLGOterms <- DMLGOterms[[s]]
    allDMLGOtermsX <- allDMLGOterms %>% filter(., allDMLGOterms$GOcat == onts[[o]])
    sigRes.all <- allRes[1:10, c(1, 2, 6)]
    colnames(sigRes.all) <- c("GOID", "GOterm", "p.value")
    # legacy 354-360
    sigRes.allGenes <- genesInTerm(GOdata, whichGO = allRes$GO.ID[1:10])
    sigRes.allGenes <- as.data.frame(vapply(sigRes.allGenes, paste, collapse = ",", character(1L)))
    colnames(sigRes.allGenes) <- c("transcript")
    sigRes.allGenes$GOID <- rownames(sigRes.allGenes)
    rownames(sigRes.allGenes) <- 1:nrow(sigRes.allGenes)
    sigRes.allGenes <- separate_rows(sigRes.allGenes, transcript, sep = ",")
    # legacy 363
    sigRes.topGO <- left_join(sigRes.all, sigRes.allGenes, by = "GOID")
    # legacy 368-371
    sigRes.allAnnot <- suppressWarnings(left_join(sigRes.topGO, allDMLGOtermsX, by = c("GOID", "transcript")))
    colnames(sigRes.allAnnot)[2] <- "topGOterm"
    colnames(sigRes.allAnnot)[10] <- "GOterm"
    stopifnot(colnames(sigRes.allAnnot)[12] == "GOcat")
    sigRes.allAnnot <- unique(sigRes.allAnnot[, -12])
    # legacy 397-407 (the product join is skipped: it adds one column and, per the archived
    # -Product.csv files, no rows; the transcript column it passes on is unchanged)
    sigRes.allMethDiff <- unique(sigRes.allAnnot %>%
                                   dplyr::select(., transcript) %>%
                                   left_join(., DMLGOterms[[s]], by = "transcript", relationship = "many-to-many") %>%
                                   filter(., GOcat == onts[[o]]) %>%
                                   dplyr::select(., geneID, chr, start, end, meth.diff))
    key <- paste(s, o)
    counts[[key]] <- data.frame(
      set = s, ont = o,
      n_table_rows = nrow(allDMLGOterms),
      GO_terms_panel = nrow(allDMLGOtermsX),
      n_topGO_rows = nrow(sigRes.topGO),
      na_transcripts = sum(is.na(sigRes.topGO$transcript)),
      gene_products_panel = nrow(sigRes.allAnnot),
      unique_genes_panel = length(na.omit(unique(sigRes.allAnnot$geneID))),
      unique_transcripts_panel = length(na.omit(unique(sigRes.allAnnot$transcript))),
      fig9_total = nrow(sigRes.allMethDiff),
      fig9_hyper = sum(sigRes.allMethDiff$meth.diff >= 0),
      fig9_hypo = sum(sigRes.allMethDiff$meth.diff <= 0),
      fig9_strict_hyper = sum(sigRes.allMethDiff$meth.diff > 0),
      fig9_strict_hypo = sum(sigRes.allMethDiff$meth.diff < 0),
      n_terms = nrow(allRes),
      n_p_below_0.01 = sum(pvalFis < 0.01),
      n_sig_transcripts = length(sigGenes(GOdata)),
      n_feasible = length(genes(GOdata)))
    out[[key]] <- list(allRes = allRes, pval = pvalFis, top10 = allRes$GO.ID[1:10], topGO = sigRes.topGO,
                       annot = sigRes.allAnnot, methdiff = sigRes.allMethDiff,
                       sig = sigGenes(GOdata), feasible = genes(GOdata),
                       inTerm = genesInTerm(GOdata, whichGO = allRes$GO.ID[1:10]))
    cat(format(Sys.time(), "%H:%M:%S"), key, "done\n")
  }
}
counts <- do.call(rbind, counts)
write.csv(counts, file.path(scratch, "A_counts.csv"), row.names = FALSE)
saveRDS(list(out = out, DMLGOterms = DMLGOterms, DMLGOterms_exact = DMLGOterms_exact,
             geneID2GO = geneID2GO), file.path(scratch, "A_port.rds"))
print(counts, row.names = FALSE)
